#include <stddef.h>
#include <stdlib.h>
#include <threads.h>

struct part { const int *values; size_t from, to; long long sum; };

static int sum_part(void *arg)
{
    struct part *p = arg;
    for (size_t i = p->from; i < p->to; i++) p->sum += p->values[i];
    return 0;
}

long long parallel_sum(const int *values, size_t count, int threads)
{
    struct part *parts = calloc((size_t)threads, sizeof *parts);
    thrd_t *ids = calloc((size_t)threads, sizeof *ids);
    long long total = 0;
    if (parts == NULL || ids == NULL)
    {
        for (size_t i = 0; i < count; i++) total += values[i];
        goto done;
    }
    for (int t = 0; t < threads; t++)
    {
        parts[t] = (struct part){ values, count * (size_t)t / (size_t)threads, count * (size_t)(t + 1) / (size_t)threads, 0 };
        thrd_create(&ids[t], sum_part, &parts[t]);
    }
    for (int t = 0; t < threads; t++)
    {
        thrd_join(ids[t], NULL);
        total += parts[t].sum;
    }
done:
    free(parts);
    free(ids);
    return total;
}
